import {TRACKS,LESSONS,EXERCISES,STORAGE_KEY,initialState,validateState,registerGenerated,dayKey,shiftDay,daily,streak,independentCount,levelFor,dueReviews,needReview,reviewAnswer,recordAttempt,getExercise,recommend,generatedSequence,generatedProgress} from './core.js';
import {PythonRunner} from './runner.js';
import {LocalTutor,SYSTEM,HINT_SYSTEM,generationPrompt,parseExercise,verifyGeneratedExercise,hintPrompt,parseHint} from './tutor.js';
import {FOCUS,codeFingerprint,rememberDiagnostic} from './practice.js';
import {metricSummary} from './metrics.js';

const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10l9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z',code:'M8 5l-6 7 6 7m8-14 6 7-6 7m-3-17-2 20',branch:'M6 3v12a4 4 0 0 0 4 4h8M6 7h8a4 4 0 0 0 4-4M3 3h6m9-2v4m-2 12h4',chart:'M4 20V10m8 10V4m8 16v-7M2 22h20',spark:'m12 2 2.6 7.4L22 12l-7.4 2.6L12 22l-2.6-7.4L2 12l7.4-2.6z',network:'M5 5l7 7 7-7M5 19l7-7 7 7M2 2h6v6H2zM16 2h6v6h-6zM2 16h6v6H2zM16 16h6v6h-6z',target:'M12 3a9 9 0 1 0 9 9M12 7a5 5 0 1 0 5 5m-5 0 9-9m-1 0h-4m4 0v4',bolt:'m13 2-9 12h7l-1 8 10-12h-7z',book:'M12 5v16M3 4c3-1 6-1 9 1 3-2 6-2 9-1v15c-3-1-6-1-9 2-3-3-6-3-9-2z',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M4 21v-2a8 8 0 0 1 16 0v2',fire:'M12 2c-2 5 3 5 1 9-2-1-3-3-3-3-5 5-6 11-1 14 6 3 13-2 11-8-1-4-5-4-8-12',arrow:'M4 12h15m-6-6 6 6-6 6',back:'M20 12H5m6-6-6 6 6 6',check:'M5 12l4 4L19 6',close:'m6 6 12 12M6 18 18 6',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0m-9-5v5l3 2',bulb:'M8 16c0-2-4-4-4-8a8 8 0 0 1 16 0c0 4-4 6-4 8M8 19h8m-7 3h6M12 3v5',brain:'M12 4c-4-5-9 0-7 4-5 2-3 8 0 8-1 5 6 8 7 3m0-15c4-5 9 0 7 4 5 2 3 8 0 8 1 5-6 8-7 3V4m-4 6 4 2 4-2m-9 5 5-1 5 1',repeat:'M4 8h13l-3-3m6 11H7l3 3M4 8v5m16 3v-5',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',info:'M12 11v6m0-10v.1M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',chevron:'m9 5 7 7-7 7'};
const icon=(name,size=22)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.code}"/></svg>`;
const rich=x=>esc(x).replace(/`([^`]+)`/g,'<code class="inline-code">$1</code>').replace(/\n/g,'<br>');
function pyrepr(x){if(x===null)return 'None';if(typeof x==='boolean')return x?'True':'False';if(Array.isArray(x))return '['+x.map(pyrepr).join(', ')+']';if(typeof x==='object')return '{'+Object.entries(x).map(([k,v])=>JSON.stringify(k)+': '+pyrepr(v)).join(', ')+'}';return JSON.stringify(x);}
let state=initialState(),recovery='';
try{const raw=localStorage.getItem(STORAGE_KEY);if(raw)state=validateState(JSON.parse(raw));}catch{recovery='I progressi salvati non sono leggibili. Puoi importare un backup dal Profilo.';}
registerGenerated(state.generated);
let route={name:'home'},feedback=null,hintCount=0,working=false,generation=null,generationError='',generationTrack=state.preferred,generationReady=null,personalJob=null,personalError='',modelCatalog=[],runnerStatus='loading',lessonFilter='all',searchTerm='',modalName=null,lastModalFocus=null;
let runner=new PythonRunner(status=>{runnerStatus=status;updatePythonStatus();});
let tutor=new LocalTutor(()=>{if(route.name==='profile'&&!modalName&&!generation&&!personalJob)render();else updateGeneration();updatePersonalHintUI();});
const root=document.getElementById('app'),modalRoot=document.getElementById('modal-root');
fetch('./models.json').then(r=>r.json()).then(items=>{modelCatalog=items;if(route.name==='profile'&&!modalName)render();}).catch(()=>toast('Non riesco a leggere il catalogo dei modelli.'));
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch{toast('Non riesco a salvare i progressi. Esporta un backup dal Profilo.');}}
let toastTimer;
function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4700);}
const trackOf=id=>TRACKS.find(t=>t.id===id);
const btn=(label,action,kind='primary',extra='')=>`<button class="btn ${kind}" data-action="${action}" ${extra}>${label}</button>`;
const badge=(track,size=22)=>`<div class="badge-icon" style="--track-color:${track.color};color:${track.color};background:${track.tint}">${icon(track.icon,size)}</div>`;
const nav=[['home','Oggi','home'],['tracks','Percorsi','branch'],['tutor','Tutor','brain'],['study','Studio','book'],['profile','Profilo','user']];
function selectedNav(){return route.name==='track'?'tracks':route.name==='exercise'?(getExercise(route.id)?.generated?'tutor':'home'):route.name;}
function shell(content){return `<header class="topbar"><a href="#" class="logo" data-action="home"><img src="icon.svg" alt="">PyDaily</a><div class="header-note"><span class="online-dot"></span>Il tuo spazio per imparare</div></header><div class="layout"><aside class="sidebar">${nav.map(([id,title,i])=>`<button class="nav-item ${selectedNav()===id?'active':''}" data-action="${id}" ${selectedNav()===id?'aria-current="page"':''}>${icon(i)}${title}${id==='study'&&dueReviews(state).length?`<span class="tag">${dueReviews(state).length}</span>`:''}</button>`).join('')}<div class="sidebar-foot">${icon('code',28)}<p>Piccoli passi.<br>Problemi veri.<br>Ogni giorno un po’ meglio.</p></div></aside><main class="main" id="main" tabindex="-1">${content.includes('data-generation-status')?'':generationHTML()}${content}</main></div><nav class="bottom-nav" aria-label="Navigazione principale">${nav.map(([id,title,i])=>`<button class="bottom-item ${selectedNav()===id?'active':''}" data-action="${id}" ${selectedNav()===id?'aria-current="page"':''}>${icon(i)}${title}</button>`).join('')}</nav>`;}
function trackCard(t){const count=independentCount(state,t.id);return `<button class="card track-card" data-action="track" data-track="${t.id}">${badge(t)}<h3>${esc(t.name)}</h3><p>${esc(t.subtitle)}</p><div class="track-meta">LIVELLO ${levelFor(state,t.id)} <span style="padding:0 5px">·</span> ${count} risolti</div><div class="progress-bar"><span style="width:${Math.min(100,count/10*100)}%;background:${t.color}"></span></div></button>`;}
function generationHTML(){
  if(!generation){
    if(generationError)return `<section class="generation-card generation-error" data-generation-status role="alert"><div><h3>La sfida non è pronta</h3><p>${esc(generationError)}</p><p>Nessuna nuova sfida è stata salvata. Le precedenti restano in Tutor.</p><p>Se il modello continua a fallire, puoi cambiarlo senza perdere le sfide salvate.</p></div><div class="generation-actions">${btn('Riprova','generate','outline',`data-track="${generationTrack}"`)}<button class="text-button" data-action="tutor-settings">Cambia modello</button><button class="text-button" data-action="dismiss-generation-error">Chiudi</button></div></section>`;
    const e=state.generated[generationReady];
    return e?`<section class="generation-card generation-ready" data-generation-status role="status">${icon('check',24)}<div><h3>La tua sfida è pronta</h3><p>${esc(e.title)} · ${esc(trackOf(e.track).name)}</p><p>Salvata in Tutor → Sfide del tutor.</p></div>${btn('Apri la sfida','exercise','primary',`data-id="${e.id}"`)}</section>`:'';
  }
  const phases={generating:['Il tutor prepara una proposta','Non è ancora una sfida pronta. Inferenza locale, massimo 3 minuti per richiesta. Puoi leggere le lezioni mentre aspetti.'],reviewing:['Il tutor rilegge la consegna','Una seconda inferenza locale prepara una soluzione indipendente e nuovi test.'],checking:['Controllo soluzione e test','Python esegue le soluzioni e confronta i risultati. Questi controlli non garantiscono correttezza assoluta.']};
  const [title,text]=phases[generation.phase];
  const progress=tutor.status.inference;
  const nativePhase={loading:'Carico il modello',prompt:'Elaboro la richiesta',tokens:'Scrivo la proposta',done:'Risposta ricevuta, da verificare'};
  const detail=progress&&generation.phase!=='checking'?`${nativePhase[progress.phase]||'Inferenza'} · ${Math.floor(progress.elapsedMs/1000)} s${progress.tokens?' · '+progress.tokens+(progress.phase==='prompt'?' token letti':' token'):''}`:'';
  return `<div class="generation-card" data-generation-status role="status"><span class="spinner"></span><div><h3>${title}</h3><p>${esc(trackOf(generation.track).name)} · ${text}</p><p class="generation-detail">Tentativo ${generation.attempt} di 2${detail?' · '+esc(detail):''}</p></div><button class="text-button" data-action="cancel-generation">Annulla</button></div>`;
}
function home(){
  const d=daily(state),done=d.solved.length,goal=state.goal,t=trackOf(state.preferred),e=recommend(state),reviews=dueReviews(state);
  const date=new Intl.DateTimeFormat('it-IT',{weekday:'long',day:'numeric',month:'long'}).format(new Date());
  return `<div class="page-heading"><p class="date">${esc(date.charAt(0).toUpperCase()+date.slice(1))}</p><h1>Un po’ di Python,<br>ogni giorno.</h1><p>Una nuova sfida. Un concetto più chiaro.</p></div>${generationHTML()}<div class="dashboard-grid"><section class="card hero"><div class="eyebrow">${done>=goal?'OBIETTIVO RAGGIUNTO · CONTINUA SE VUOI':'LA TUA SFIDA DI OGGI'}</div><h2>${esc(e.title)}</h2><p>${esc(t.name)} · Livello ${e.level} · circa ${e.minutes} min</p>${btn(`Inizia la sfida ${icon('arrow',17)}`,'exercise','lime',`data-id="${e.id}"`)}<div class="hero-art" aria-hidden="true"><div class="hero-code"><span>def</span> ogni_giorno():<br>&nbsp; <span>return</span> +1</div><div class="small-orbit">${icon('spark',19)}</div></div></section><section class="card goal-card"><div class="goal-ring" style="--progress:${Math.min(1,done/goal)*360}deg"><div>${done}<small>/${goal}</small></div></div><div><h3>${done>=goal?'Ottimo, hai fatto il tuo passo.':'Il tuo obiettivo giornaliero'}</h3><p>${done>=goal?'Domani continuiamo da qui.':`${Math.max(0,goal-done)} ${goal-done===1?'problema ti aspetta':'problemi ti aspettano'}. Nessuna fretta.`}</p></div><button class="text-button" data-action="profile">Modifica ${icon('chevron',14)}</button></section></div><div class="stats-strip"><div class="card stat"><div class="badge-icon" style="color:#bb8650">${icon('fire')}</div><div><b>${streak(state)}</b><small>giorni di fila</small></div></div><div class="card stat"><div class="badge-icon" style="color:#8a994c">${icon('bolt')}</div><div><b>${state.xp}</b><small>punti XP</small></div></div><div class="card stat"><div class="badge-icon" style="color:#427d69">${icon('check')}</div><div><b>${independentCount(state)}</b><small>risolti da te</small></div></div></div><div class="section-head"><h2>Scegli la tua direzione</h2><button class="text-button" data-action="tracks">Tutti i percorsi ${icon('arrow',15)}</button></div><div class="tracks-grid">${[t,...TRACKS.filter(x=>x.id!==t.id&&['data','ml','python'].includes(x.id))].slice(0,3).map(trackCard).join('')}</div><section class="tutor-banner"><div class="badge-icon" style="color:#627a43;background:#e1e9d2">${icon('brain')}</div><div><h3>${tutor.status.available?'Il tuo tutor, sul tuo dispositivo':'Una progressione che continua'}</h3><p>${tutor.status.available?'Genera una sfida nuova per il tuo livello, senza inviare il codice a un server.':'Attiva il modello locale per creare problemi nuovi oltre quelli inclusi.'}</p></div><button class="text-button" data-action="${tutor.status.available?'generate':'tutor-settings'}" ${generation?'disabled':''}>${tutor.status.available?'Genera una sfida':'Attiva il tutor'} ${icon('arrow',15)}</button></section><div class="section-head"><h2>Il prossimo concetto da chiarire</h2><button class="text-button" data-action="study">Apri lo studio ${icon('arrow',15)}</button></div><section class="card">${reviews.length?reviews.slice(0,2).map(l=>`<button class="review-row" data-action="lesson" data-id="${l.id}">${badge(trackOf(l.track),19)}<div><h3>${esc(l.title)}</h3><p>${esc(l.reason)} · ${l.minutes} min</p></div><span class="chevron">${icon('chevron',17)}</span></button>`).join(''):`<button class="review-row" data-action="lesson" data-id="${e.lesson}">${badge(t,19)}<div><h3>${esc(LESSONS.find(l=>l.id===e.lesson).title)}</h3><p>Scalda le idee prima di iniziare · ${LESSONS.find(l=>l.id===e.lesson).minutes} min</p></div><span class="chevron">${icon('chevron',17)}</span></button>`}</section>`;
}
function tracks(){return `<div class="page-heading"><p class="date">SETTE DIREZIONI, UN PASSO ALLA VOLTA</p><h1>Il tuo percorso,<br>le tue curiosità.</h1><p>La difficoltà cresce in ogni ramo. Puoi esplorarli tutti.</p></div>${generationHTML()}<div class="tracks-grid">${TRACKS.map(trackCard).join('')}</div><p class="footer-caption">Due problemi risolti senza vedere la soluzione fanno salire di un livello. I suggerimenti sono sempre disponibili. Dopo gli esercizi inclusi, continua con il tutor locale o con nuovi dati nei laboratori.</p>`;}
function trackPage(){
  const t=trackOf(route.track),count=independentCount(state,t.id),level=levelFor(state,t.id),bank=EXERCISES.filter(e=>e.track===t.id),ai=generatedProgress(state,t.id);
  return `<button class="page-back" data-action="tracks">${icon('back',17)} Tutti i percorsi</button><section class="card track-hero" style="background:${t.tint}">${badge(t,26)}<div><div class="eyebrow" style="color:${t.color}">IL TUO PERCORSO</div><h1>${esc(t.name)}</h1><p>${esc(t.description)}</p></div></section><div class="level-steps">${[1,2,3,4,5].map(n=>`<span class="level-step ${n<=level?'filled':''}" style="${n<=level?`background:${t.color}`:''}"></span>`).join('')}</div><div class="level-label"><span>Livello ${level} · ${count} problemi autonomi</span><span>${2-count%2} al prossimo livello</span></div><div class="row between" style="margin:21px 0 3px;flex-wrap:wrap">${btn(`Continua ${icon('arrow',17)}`,'exercise','primary',`data-id="${recommend(state,t.id).id}"`)}<button class="text-button" data-action="set-preferred" data-track="${t.id}">${state.preferred===t.id?'Percorso quotidiano selezionato':'Scegli per le sfide quotidiane'}</button></div>${generationHTML()}
  <section class="tutor-banner"><div>${icon('brain',27)}</div><div><h3>Sfide del tutor</h3><p>${ai.total} salvate · ${ai.independent} risolte da te · ${ai.pending} da svolgere</p></div><button class="text-button" data-action="tutor-library" data-track="${t.id}">Apri le sfide ${icon('arrow',15)}</button></section><div class="section-head"><h2>Esercizi inclusi</h2></div>
  <div class="exercise-list">${bank.map((e,i)=>{const solved=state.solved[e.id];return `<button class="card exercise-row" data-action="exercise" data-id="${e.id}"><span class="exercise-number">${solved?icon(solved.assisted?'book':'check',16):String(i+1).padStart(2,'0')}</span><div><h3>${esc(e.title)}</h3><small>Livello ${e.level} · ${e.minutes} min</small></div><span class="tag">${solved?(solved.assisted?'Guidato':'Risolto'):e.level===level?'Per te':`${e.level<=2?'Basi':e.level<=4?'Intermedio':'Avanzato'}`}</span></button>`;}).join('')}</div><section class="tutor-banner"><div>${icon('brain',27)}</div><div><h3>Un problema che non hai mai visto</h3><p>Il tutor combina il tuo livello con i concetti da consolidare.</p></div><button class="text-button" data-action="generate" data-track="${t.id}" ${generation?'disabled':''}>Genera ${icon('arrow',15)}</button></section>`;
}
const challengeLabels={ready:'Da iniziare','in-progress':'In corso',guided:'Guidata',solved:'Risolta da te'};
function tutorTrackHTML(t){
  const progress=generatedProgress(state,t.id),count=independentCount(state,t.id),locked=generation||working||personalJob||tutor.status.busy;
  return `<section class="challenge-track" data-challenge-track="${t.id}"><div class="card challenge-overview"><div class="row">${badge(t)}<div><h2>${esc(t.name)}</h2><p>Livello ${levelFor(state,t.id)} · ${2-count%2} problemi autonomi al prossimo livello</p></div></div><p>${progress.independent} autonome · ${progress.guided} guidate · ${progress.pending} da svolgere</p><div class="progress-bar" role="progressbar" aria-label="Sfide completate in ${esc(t.name)}" aria-valuemin="0" aria-valuemax="${Math.max(1,progress.total)}" aria-valuenow="${progress.completed}"><span style="width:${progress.total?progress.completed/progress.total*100:0}%"></span></div><div class="challenge-actions">${progress.next?btn(`${progress.next.status==='guided'?'Riprova da te':'Continua'} · sfida ${progress.next.number}`,'exercise','primary',`data-id="${progress.next.exercise.id}"`):''}${btn('Genera una sfida','generate','outline',`data-track="${t.id}" ${locked?'disabled':''}`)}</div></div>
  ${progress.total?`<ol class="challenge-list" aria-label="Sequenza delle sfide di ${esc(t.name)}">${progress.entries.map(({exercise:e,number,status})=>`<li><button class="card exercise-row challenge-row" data-action="exercise" data-id="${e.id}" data-status="${status}"><span class="exercise-number" aria-hidden="true">${String(number).padStart(2,'0')}</span><div class="challenge-copy"><small>Sfida ${number} · livello ${e.level}</small><h3>${esc(e.title)}</h3></div><span class="tag">${challengeLabels[status]}</span>${icon('chevron',16)}</button></li>`).join('')}</ol>`:`<div class="card empty"><h3>La prima sfida ti aspetta</h3><p>Genera una proposta per questo percorso. Apparirà qui soltanto dopo la revisione e i controlli Python.</p></div>`}</section>`;
}
function tutorPage(){
  const filter=route.track||'all',selected=filter==='all'?null:trackOf(filter),progress=generatedProgress(state,selected?.id);
  const visible=selected?[selected]:TRACKS.filter(t=>generatedSequence(state,t.id).length),groups=visible.length?visible:[trackOf(state.preferred)];
  return `<div class="page-heading"><p class="date">UNA SEQUENZA, NON SFIDE SPARSE</p><h1>Sfide del tutor</h1><p>Le sfide salvate restano in ordine di creazione, numerate in ogni percorso. Riprendi una bozza o rivedi un risultato, anche senza un modello attivo.</p></div>${generationHTML()}<div class="challenge-stats"><div class="card"><b>${progress.total}</b><span>sfide salvate</span></div><div class="card"><b>${progress.independent}</b><span>risolte da te</span></div><div class="card"><b>${progress.pending}</b><span>da svolgere</span></div></div><div class="filters challenge-filters" role="group" aria-label="Percorso delle sfide"><button class="filter ${filter==='all'?'active':''}" data-action="tutor-filter" data-track="all" aria-pressed="${filter==='all'}">Tutti</button>${TRACKS.map(t=>`<button class="filter ${filter===t.id?'active':''}" data-action="tutor-filter" data-track="${t.id}" aria-pressed="${filter===t.id}">${esc(t.name)}</button>`).join('')}</div>${groups.map(tutorTrackHTML).join('')}<p class="footer-caption">Il livello è quello del percorso e include anche gli esercizi già presenti: due problemi diversi risolti autonomamente lo aumentano. Tip e indizi non lo bloccano; una soluzione guidata non conta come autonoma. I controlli delle nuove sfide non garantiscono correttezza semantica assoluta.</p><button class="text-button" data-action="tutor-settings">${icon('brain',17)} Gestisci il modello locale</button>`;
}
function pythonStatusHTML(){const names={loading:'Avvio Python…',ready:'Pronto · offline',running:'Verifica in corso…',error:'Python non pronto'};return `<span class="online-dot" style="background:${runnerStatus==='ready'?'#b8d386':'#d8bd73'}"></span>${names[runnerStatus]||''}`;}
function updatePythonStatus(){document.querySelectorAll('.python-status').forEach(el=>el.innerHTML=pythonStatusHTML());}
function feedbackHTML(e){if(!feedback)return '';const {result,gain}=feedback;if(feedback.id!==e.id)return '';const passed=result.passed;const hintError=result.cases.find(c=>!c.passed&&c.actual===null&&c.expected!==null);return `<section class="card feedback ${passed?'':'fail'}" aria-live="polite"><div class="row">${icon(passed?'check':'info',22)}<h3>${passed?(gain?.promoted?'Un passo avanti, un livello in più!':'Tutti i test superati.'):'Ci sei vicino. Guardiamo il passaggio.'}</h3></div><p>${passed?`${gain?.xp?`+${gain.xp} XP. `:''}${state.solved[e.id]?.assisted?'Soluzione guidata salvata. Domani potrai riprovarla da te.':gain?.newSolved?'Questo problema entra nei tuoi progressi.':'Hai consolidato un problema già risolto.'}`:result.error?rich(result.error):hintError?'La funzione restituisce None. Controlla di usare return, oltre a print.':'Il risultato non coincide ancora con tutti i casi. Apri un test per confrontarlo.'}</p>${result.cases.length?`<div class="test-chips">${result.cases.map((c,i)=>`<span class="test-chip ${c.passed?'':'fail'}">${icon(c.passed?'check':'close',12)} Test ${i+1}</span>`).join('')}</div>`:''}${!passed?result.cases.map((c,i)=>`<details class="test-detail" ${!c.passed&&i===result.cases.findIndex(x=>!x.passed)?'open':''}><summary>Test ${i+1} · ${c.passed?'corretto':'da rivedere'}</summary><pre>Ingresso: ${esc(pyrepr(e.cases[i].args))}\nAtteso: ${esc(pyrepr(c.expected))}\nOttenuto: ${esc(pyrepr(c.actual))}</pre></details>`).join(''):btn(`Prossimo problema ${icon('arrow',16)}`,'next','primary',`data-track="${e.track}"`)}${result.output?`<details class="test-detail"><summary>Output di print</summary><pre>${esc(result.output)}</pre></details>`:''}</section>`;}
function hintsHTML(e){return e.tips.slice(0,hintCount).map((tip,i)=>`<section class="hint"><b>SUGGERIMENTO ${i+1} DI ${e.tips.length}</b><p>${rich(tip)}</p></section>`).join('');}
function hintLabel(e){return `${icon('bulb',17)} ${hintCount>=e.tips.length?'Rileggi i suggerimenti':'Dammi un tip'}`;}
function editorToolsHTML(){
  const shortcuts=[['    ','4 spazi','Inserisci 4 spazi'],[': ',':','Inserisci due punti'],['()','( )','Inserisci parentesi tonde'],['[]','[ ]','Inserisci parentesi quadre'],['""','" "','Inserisci virgolette'],[' == ','==','Inserisci confronto di uguaglianza'],['    return ','return','Inserisci return']];
  return `<div class="keyboard-tools" role="group" aria-label="Scorciatoie per scrivere codice">${shortcuts.map(([value,label,title])=>`<button data-action="insert" data-value="${esc(value)}" aria-label="${title}" title="${title}">${esc(label)}</button>`).join('')}<button data-action="reset-code">Ripristina codice</button></div>`;
}
function exercisePage(){
  const e=getExercise(route.id);if(!e){route={name:'home'};return home();}const t=trackOf(e.track),draft=state.drafts[e.id]??e.starter;
  const entry=e.generated?generatedSequence(state,e.track).find(item=>item.exercise.id===e.id):null;
  return `<button class="page-back" data-action="${e.generated?'tutor-library':'back-track'}" data-track="${e.track}">${icon('back',17)} ${e.generated?'Sfide del tutor · ':''}${esc(t.name)}</button><div class="exercise-header"><div><span class="tag">${icon(e.generated?'brain':'code',14)} ${entry?`Sfida ${entry.number} · ${esc(t.name)} · controlli superati`:esc(t.name)} · livello ${e.level}</span><h1>${esc(e.title)}</h1></div></div>${generationHTML()}<div class="exercise-grid"><div><section class="card contract"><h3>La tua missione</h3><p>${rich(e.description)}</p>${e.cases.slice(0,2).map((c,i)=>`<div class="sample"><span class="eyebrow muted" style="font-size:8px">ESEMPIO ${i+1}</span><br><code>${esc(e.function)}(${esc(c.args.map(pyrepr).join(', '))})<br><span style="color:#427d69">→ ${esc(pyrepr(c.expected))}</span></code></div>`).join('')}</section><section class="card editor-card"><div class="editor-top"><span>${icon('code',15)} soluzione.py</span><span class="python-status">${pythonStatusHTML()}</span></div><div class="editor"><div class="line-numbers" aria-hidden="true">${draft.split('\n').map((_,i)=>i+1).join('\n')}</div><textarea id="code-editor" aria-label="Il tuo codice Python" spellcheck="false" autocomplete="off" autocorrect="off" autocapitalize="off" wrap="off">${esc(draft)}</textarea></div>${editorToolsHTML()}</section><div class="editor-actions">${btn(`${working?'<span class="spinner"></span>':icon('check',18)} ${working?'Controllo…':'Verifica la soluzione'}`,'run','primary',working||generation||personalJob?'disabled':'')}${runnerStatus==='error'?btn('Riprova Python','restart-python','secondary'):''}</div>${feedbackHTML(e)}<div id="hint-panel" role="region" aria-label="Suggerimenti sbloccati" aria-live="polite">${hintsHTML(e)}</div><div id="personal-hint-panel" role="region" aria-label="Indizi sul tuo codice" aria-live="polite">${personalHintsHTML(e)}</div></div><aside class="card assist-card"><h3>Impara mentre provi.</h3><p>Un aiuto al momento giusto vale più di una risposta memorizzata.</p>${btn(hintLabel(e),'hint','outline')}${btn(`${icon('book',17)} Non ho capito`,'explain','outline')}${btn('Mostra la soluzione','solution','secondary solution-btn')}<div id="personal-hint-controls">${personalHintControls()}</div><p class="footer-caption" style="margin:3px 0 0">Tip e indizi mantengono la prova autonoma. La soluzione completa la rende guidata. Gli indizi del modello possono essere imprecisi.</p></aside></div>`;
}
function personalHintControls(){return personalJob?btn('Annulla indizio','cancel-personal-hint','outline'):tutor.status.available?btn(`${icon('brain',17)} Indizio sul mio codice`,'personal-hint','outline',working||generation||tutor.status.busy?'disabled':''):`<button class="text-button" data-action="tutor-settings">Attiva il tutor per un indizio sul codice</button>`;}
function personalHintsHTML(e){
  const hash=codeFingerprint(state.drafts[e.id]??e.starter),saved=state.attempts[e.id]?.personalHints||[];
  return `${saved.map(h=>`<section class="hint personal-hint"><b>INDIZIO PERSONALE · ${esc(FOCUS[h.focus])}</b><p>${rich(h.text)}</p>${h.codeHash!==hash?'<small>Riferito a una bozza precedente: verifica se è ancora utile.</small>':''}</section>`).join('')}${personalJob?.id===e.id?`<section class="hint" role="status"><span class="spinner"></span> ${personalJob.phase==='checking'?'Python verifica la bozza senza assegnare XP.':'Il tutor prepara un solo indizio, non la soluzione. Massimo 60 secondi.'}</section>`:''}${personalError?`<section class="hint" role="alert"><p>${esc(personalError)}</p></section>`:''}`;
}
function updatePersonalHintUI(){
  if(route.name!=='exercise')return;const e=getExercise(route.id);if(!e)return;
  const panel=document.getElementById('personal-hint-panel'),controls=document.getElementById('personal-hint-controls'),active=document.activeElement?.dataset.action;
  if(panel)panel.innerHTML=personalHintsHTML(e);if(controls)controls.innerHTML=personalHintControls();
  const run=document.querySelector('[data-action="run"]');if(run)run.disabled=!!(working||generation||personalJob);
  if(active==='cancel-personal-hint')document.querySelector('[data-action="cancel-personal-hint"]')?.focus({preventScroll:true});
}
function cancelPersonalHint(){if(!personalJob)return;const job=personalJob;personalJob=null;job.cancelled=true;if(job.phase==='checking')runner.restart();else tutor.cancel();updatePersonalHintUI();}
async function personalHint(){
  if(working||generation||personalJob||tutor.status.busy)return;
  const e=getExercise(route.id),code=document.getElementById('code-editor')?.value;if(!e||code===undefined||!tutor.status.available)return;
  persistEditor();personalError='';const job={id:e.id,phase:'checking',cancelled:false};personalJob=job;updatePersonalHintUI();
  const current=()=>!job.cancelled&&route.name==='exercise'&&route.id===e.id&&state.drafts[e.id]===code;
  try{
    const result=await runner.run({code,function:e.function,cases:e.cases}).catch(error=>{if(error.pythonTimeout)return {passed:false,cases:[],output:'',error:error.message};throw error;});if(!current())return;
    const diagnostic=rememberDiagnostic(state,e,code,result);if(!diagnostic.passed)needReview(state,e.lesson);save();job.phase='hinting';updatePersonalHintUI();
    const text=await tutor.generate(HINT_SYSTEM,hintPrompt(e,code,diagnostic),{kind:'hint'});if(!current())return;
    const hint=parseHint(text,e),attempt=state.attempts[e.id];attempt.personalHints=[...(attempt.personalHints||[]),{...hint,codeHash:codeFingerprint(code),day:dayKey()}].slice(-3);save();
  }catch(error){if(current())personalError=error.message;}
  finally{if(personalJob===job){personalJob=null;updatePersonalHintUI();}}
}
function study(){const reviews=dueReviews(state),lessons=LESSONS.filter(l=>(lessonFilter==='all'||lessonFilter===l.track)&&(!searchTerm||(l.title+' '+l.intro).toLowerCase().includes(searchTerm.toLowerCase())));return `<div class="page-heading"><p class="date">CAPIRE, POI RIPROVARE</p><h1>Fai spazio<br>alle idee.</h1><p>Mini-lezioni semplici, esempi e una domanda per capire se è chiaro.</p></div>${reviews.length?`<section class="card" style="margin-bottom:22px;background:#f0f4e8"><div class="row between"><h3>Da ripassare oggi</h3><span class="tag">${reviews.length}</span></div>${reviews.map(l=>`<button class="review-row" data-action="lesson" data-id="${l.id}"><div><h3>${esc(l.title)}</h3><p>${esc(l.reason)}</p></div><span class="chevron">${icon('chevron',17)}</span></button>`).join('')}</section>`:''}<input class="search" id="lesson-search" type="search" aria-label="Cerca un argomento" placeholder="Cerca un argomento: funzioni, gradienti…" value="${esc(searchTerm)}"><div class="filters"><button class="filter ${lessonFilter==='all'?'active':''}" data-action="filter" data-track="all">Tutti</button>${TRACKS.map(t=>`<button class="filter ${lessonFilter===t.id?'active':''}" data-action="filter" data-track="${t.id}">${esc(t.name)}</button>`).join('')}</div><div class="lessons-grid" id="lesson-results">${lessonCards(lessons)}</div><p class="footer-caption">Dopo una risposta corretta, il concetto torna tra 1, 3, 7 e 14 giorni. Dopo un errore, riparti dalla spiegazione.</p>`;}
function lessonCards(lessons){return lessons.length?lessons.map(l=>`<button class="card lesson-card" data-action="lesson" data-id="${l.id}">${badge(trackOf(l.track),19)}<div><h3>${esc(l.title)}</h3><p>${esc(trackOf(l.track).name)} · ${l.minutes} min ${state.read[l.id]?'· studiato':''}</p></div></button>`).join(''):'<section class="card empty"><p>Nessuna lezione trovata. Prova una parola diversa.</p></section>';}
function appearanceHTML(){const preference=window.PyDailyTheme.getPreference();return `<section class="card appearance-settings"><h3>Aspetto</h3><div class="settings-row"><div><label for="theme-preference">Tema dell’app</label><p>Scegli i colori che preferisci.</p></div><select class="select" id="theme-preference">${[['light','Chiaro'],['dark','Scuro'],['system','Come il telefono']].map(([value,label])=>`<option value="${value}" ${preference===value?'selected':''}>${label}</option>`).join('')}</select></div><p class="footer-caption" style="margin-top:0">La scelta rimane su questo dispositivo e non modifica i progressi.</p></section>`;}
function profile(){const days=Array.from({length:28},(_,i)=>shiftDay(dayKey(),i-27));const totalAttempts=Object.values(state.daily).reduce((n,d)=>n+d.attempts,0);return `<div class="page-heading"><p class="date">I TUOI PICCOLI PASSI, VISIBILI</p><h1>La costanza<br>prende forma.</h1><p>Progressi sul dispositivo. Nessun account da creare.</p></div><div class="profile-grid"><div><section class="card"><h3>Il tuo percorso fin qui</h3><div class="big-stats"><div><b>${independentCount(state)}</b><small>problemi autonomi</small></div><div><b>${state.xp}</b><small>punti XP</small></div><div><b>${Object.keys(state.read).length}</b><small>lezioni studiate</small></div></div><hr class="divider"><div class="row between"><h3 style="font-size:12px">Le ultime 4 settimane</h3><span class="muted" style="font-size:10px">${streak(state)} giorni di fila</span></div><div class="heatmap">${days.map(key=>{const n=daily(state,key).solved.length;return `<span class="heat ${n>=state.goal?'goal':n?'some':''} ${key===dayKey()?'today':''}" title="${key}: ${n} problemi" aria-label="${key}: ${n} problemi"></span>`;}).join('')}</div><div class="heat-legend"><span>Ogni casella è un giorno</span><span>${totalAttempts} verifiche totali</span></div></section><section class="card model-card" id="tutor-card"><div class="row">${icon('brain',27)}<div><h2 style="font-size:19px">Il tuo tutor locale</h2><small class="muted">Nuove sfide, anche senza internet</small></div></div><p>Un piccolo modello specializzato nel codice crea problemi per il tuo livello. Python controlla soluzione e test prima di proporteli.</p>${window.Native?modelPanel():`<div class="model-choice"><div><h3>Disponibile nell’app Android</h3><p>Installa l’APK per scaricare un modello GGUF ed eseguirlo sul dispositivo. Qui puoi provare l’editor e tutti gli esercizi inclusi.</p></div></div>`}<p class="footer-caption">Il download richiede internet e spazio libero. Dopo, prompt e codice restano sul dispositivo. La velocità dipende dal telefono. Puoi importare un altro GGUF compatibile con llama.cpp.</p></section></div><div class="stack">${appearanceHTML()}<section class="card"><h3>Un obiettivo sostenibile</h3><p class="muted" style="font-size:11px;margin-top:8px">Quanti problemi vuoi risolvere al giorno?</p><div class="goal-options">${[1,3,5].map(n=>`<button class="goal-choice ${state.goal===n?'active':''}" data-action="goal" data-goal="${n}">${n}<span>${n===1?'con calma':n===3?'passo costante':'più slancio'}</span></button>`).join('')}</div><hr class="divider"><div class="settings-row"><div><h3>La tua direzione</h3><p>Per la sfida quotidiana</p></div><select class="select" id="preferred-track" aria-label="Percorso quotidiano">${TRACKS.map(t=>`<option value="${t.id}" ${state.preferred===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></div><div class="settings-row"><div><h3>Un promemoria gentile</h3><p>${window.Native?'Una notifica al giorno':'Disponibile nell’app Android'}</p></div><button class="toggle ${state.reminder.enabled?'active':''}" data-action="reminder" aria-label="Promemoria quotidiano" aria-pressed="${state.reminder.enabled}" ${window.Native?'':'disabled'}></button></div><input class="time-input" type="time" id="reminder-time" aria-label="Orario del promemoria" value="${esc(state.reminder.time)}"></section><section class="card"><h3>I tuoi progressi, con te</h3><p class="muted" style="font-size:11px;margin:10px 0 16px">Esporta un backup prima di cambiare dispositivo o reinstallare l’app.</p>${btn(`${icon('download',16)} Esporta progressi`,'export','outline full')}${btn('Importa un backup','import','secondary full','style="margin-top:9px"')}<input type="file" id="backup-file" accept="application/json,.json" class="hidden"><p class="footer-caption">Il backup include codice, lezioni e sfide generate. I pesi del modello si scaricano separatamente.</p></section></div></div>`;}
function modelPanel(){
  const s=tutor.status;if(s.downloading)return `<div class="model-progress"><div class="row between"><small>${esc(s.message||'Download in corso…')}</small><strong>${s.progress||0}%</strong></div><div class="progress-bar" style="margin:12px 0"><span style="width:${s.progress||0}%"></span></div><button class="text-button" data-action="model-action" data-model-action="cancelDownload">Interrompi e riprendi più tardi</button></div>`;
  const locked=s.busy||generation||working||personalJob;
  return `${s.available?`<div class="model-choice"><div><span class="tag">${icon('check',12)} PRONTO</span><h3>${esc(s.model)}</h3><p>Inferenza interamente sul dispositivo</p></div>${btn('Genera','generate','primary',locked?'disabled':'')}</div>`:''}${modelCatalog.map(m=>{const installed=s.installed?.includes(m.id),partial=s.partial?.includes(m.id),active=s.activeId===m.id;return `<div class="model-choice"><div><h3>${esc(m.name)}</h3><span class="tag">${esc(m.role)}</span><p>${esc(m.description)}</p><small class="muted model-source">Fonte: ${esc(m.source)} · ${esc(m.license)}</small></div><div class="model-buttons">${btn(active?'Attivo':installed?'Usa':partial?'Riprendi':'Scarica','model-action','outline',`data-model-action="download:${m.id}" ${locked||active?'disabled':''}`)}${installed||partial?`<button class="text-button danger" data-action="remove-cached-model" data-model-id="${m.id}" ${locked?'disabled':''}>Rimuovi</button>`:''}${m.requiresConsent?'<button class="text-button" data-action="mobile-license">Leggi la licenza</button>':''}</div></div>`;}).join('')}<p class="footer-caption">Le dimensioni indicate sono dei file, non della RAM totale: servono anche cache del contesto, WebView e Python/NumPy. Le nuove opzioni sono sperimentali, senza una classifica di velocità o qualità già misurata.</p><div class="row between"><button class="text-button" data-action="model-action" data-model-action="pick" ${locked?'disabled':''}>Importa GGUF</button>${s.available?`<button class="text-button danger" data-action="delete-model" ${locked?'disabled':''}>Libera spazio</button>`:''}</div>${s.message?`<p class="model-message">${esc(s.message)}</p>`:''}${s.ramGB?`<p class="footer-caption">RAM del telefono: circa ${s.ramGB} GB${s.availableRamGB!==undefined?` · disponibile ora: ${s.availableRamGB} GB`:''}. Se serve, prova Qwen3-0.6B.</p>`:''}${metricsPanel()}`;
}
function metricsPanel(){const entries=tutor.measurements,summary=metricSummary(entries);return `<section class="tutor-metrics"><h3>Misure locali del tutor</h3><p class="footer-caption">Ultime 40 operazioni, senza prompt o codice. Cicli accettati: ${summary.accepted}/${summary.cycles}${summary.medianMs===null?'':` · mediana: ${(summary.medianMs/1000).toFixed(1)} s`}. Un ciclo include generazione, revisione e controlli Python.</p>${entries.length?`<div class="metrics-list">${entries.slice(-6).reverse().map(m=>`<div><b>${esc(m.model)}</b><p>${m.kind==='cycle'?'Sfida completa':m.kind==='hint'?'Indizio':'Inferenza'} · ${esc(({completed:'risposta completata',failed:'errore',accepted:'accettata',rejected:'scartata',cancelled:'annullata',timeout:'timeout'})[m.status])} · ${((m.elapsedMs||0)/1000).toFixed(1)} s${m.decodeMs&&m.decodeTokens?` · ${(m.decodeTokens*1000/m.decodeMs).toFixed(1)} token/s`:''}${m.peakProcessRssMiB?` · picco RSS processo ${m.peakProcessRssMiB.toFixed(0)} MiB`:''}</p></div>`).join('')}</div>`:'<p class="footer-caption">Nessuna misura in questa installazione.</p>'}<p class="footer-caption">RSS: massimo del processo app da quando è stato avviato, non RAM del solo modello né di tutta l’app con i processi WebView. Le misure non attestano correttezza didattica.</p>${btn('Esporta misure','export-metrics','outline',entries.length?'':'disabled')}</section>`;}
async function mobileLicense(action=''){
  try{const response=await fetch('./vendor/licenses/mobilellm-r15.txt');if(!response.ok)throw Error('Licenza non disponibile');const text=await response.text();modal(`<div class="modal-top"><h2>MobileLLM: uso non commerciale</h2><button class="icon-button" data-action="close-modal" aria-label="Chiudi">${icon('close')}</button></div><p class="lesson-intro">La licenza FAIR Noncommercial Research limita l’uso a ricerca, sviluppo e studio non commerciali. Il GGUF è una conversione comunitaria del modello Meta, non una pubblicazione ufficiale Meta. Non è un tutor italiano già collaudato.</p><pre class="license-text">${esc(text)}</pre><label class="license-consent"><input id="fair-consent" type="checkbox"> Ho letto e accetto la licenza e la Acceptable Use Policy; userò il modello soltanto per usi non commerciali consentiti.</label>${btn(action?'Accetta e scarica':'Accetta','accept-mobile-license','primary',`data-next-action="${esc(action)}"`)}`,'license');}catch{toast('Licenza non disponibile: non avvio il download.');}
}
function modelAction(action){if((generation||working||personalJob)&&action!=='cancelDownload'){toast('Attendi o annulla la richiesta prima di cambiare modello.');return;}const m=modelCatalog.find(m=>action==='download:'+m.id);if(m?.requiresConsent&&!tutor.status.fairConsent){mobileLicense(action);return;}try{tutor.action(action);}catch(error){toast(error.message);}}
function updateGeneration(){
  const el=document.querySelector('[data-generation-status]'),active=document.activeElement?.dataset.action,html=generationHTML();
  if(html){const fresh=document.createElement('div');fresh.innerHTML=html;if(el)el.replaceWith(fresh.firstElementChild);else document.getElementById('main')?.prepend(fresh.firstElementChild);}
  else el?.remove();
  if(active==='cancel-generation')document.querySelector('[data-action="cancel-generation"]')?.focus({preventScroll:true});
  document.querySelectorAll('[data-action="generate"]').forEach(button=>button.disabled=!!(generation||working||personalJob||tutor.status.busy));
}
function render(){root.innerHTML=shell(route.name==='home'?home():route.name==='tracks'?tracks():route.name==='track'?trackPage():route.name==='tutor'?tutorPage():route.name==='exercise'?exercisePage():route.name==='study'?study():profile());bindEditor();}
function navigate(name,extra={}){if(route.name==='exercise')persistEditor();cancelPersonalHint();personalError='';route={name,...extra};feedback=null;const unlocked=state.attempts[route.id]?.tipsUnlocked;hintCount=Number.isInteger(unlocked)?Math.max(0,Math.min(getExercise(route.id)?.tips.length||0,unlocked)):0;render();window.scrollTo({top:0,behavior:'instant'});}
function persistEditor(){const el=document.getElementById('code-editor');if(el&&route.id){state.drafts[route.id]=el.value;save();}}
function bindEditor(){const el=document.getElementById('code-editor');if(!el)return;el.addEventListener('input',()=>{state.drafts[route.id]=el.value;document.querySelector('.line-numbers').textContent=el.value.split('\n').map((_,i)=>i+1).join('\n');save();updatePersonalHintUI();});el.addEventListener('scroll',()=>{document.querySelector('.line-numbers').scrollTop=el.scrollTop;});el.addEventListener('keydown',event=>{if(event.key==='Tab'){event.preventDefault();insertCode('    ');}if(event.key==='Enter'){event.preventDefault();const before=el.value.slice(0,el.selectionStart),line=before.split('\n').at(-1);insertCode('\n'+(line.match(/^\s*/)?.[0]||'')+(line.trimEnd().endsWith(':')?'    ':''));}});}
function insertCode(value){const el=document.getElementById('code-editor');if(!el)return;const start=el.selectionStart,end=el.selectionEnd;el.setRangeText(value,start,end,'end');if(['()','[]','""'].includes(value))el.setSelectionRange(start+1,start+1);el.focus();el.dispatchEvent(new Event('input'));}
function openExercise(id){if(generationReady===id)generationReady=null;closeModal();navigate('exercise',{id});}
function closeModal(){modalRoot.innerHTML='';modalName=null;document.body.style.overflow='';if(lastModalFocus&&lastModalFocus.isConnected)lastModalFocus.focus();}
function modal(content,name='general'){lastModalFocus=document.activeElement;modalName=name;modalRoot.innerHTML=`<div class="modal-backdrop" data-action="backdrop"><section class="modal ${name==='onboarding'?'onboarding':'lesson-modal'}" role="dialog" aria-modal="true" aria-label="${name==='onboarding'?'Benvenuto in PyDaily':'Studio e informazioni'}">${content}</section></div>`;document.body.style.overflow='hidden';modalRoot.querySelector('button')?.focus();}
function openLesson(id){const l=LESSONS.find(x=>x.id===id);if(!l)return;modal(`<div class="modal-top"><span class="tag">${icon('book',13)} ${esc(trackOf(l.track).name)} · ${l.minutes} min</span><button class="icon-button" data-action="close-modal" aria-label="Chiudi la lezione">${icon('close',20)}</button></div><h2>${esc(l.title)}</h2><p class="lesson-intro">${rich(l.intro)}</p>${l.sections.map(section=>`<section class="lesson-section"><h3>${esc(section.title)}</h3><p>${rich(section.text)}</p>${section.code?`<pre>${esc(section.code)}</pre>`:''}</section>`).join('')}<section class="quiz" id="lesson-quiz"><div class="eyebrow muted">PROVIAMO A CAPIRLO</div><h3>${esc(l.quiz.question)}</h3>${l.quiz.choices.map((c,i)=>`<button class="quiz-choice" data-action="quiz" data-id="${id}" data-index="${i}"><span class="letter">${String.fromCharCode(65+i)}</span>${esc(c)}</button>`).join('')}<div id="quiz-explanation"></div></section><div class="row" style="margin-top:21px;flex-wrap:wrap">${btn(`Metti in pratica ${icon('arrow',16)}`,'lesson-practice','primary',`data-id="${id}"`)}<button class="text-button" data-action="close-modal">Torna all’app</button></div>`,'lesson');}
function onboarding(){modal(`<div class="logo"><img src="icon.svg" alt="">PyDaily</div><div class="onboard-art" aria-hidden="true"><div class="onboard-terminal"><div class="dots">● ● ●</div>def un_passo():<br>&nbsp; prova()<br>&nbsp; capisci()<br>&nbsp; return progresso</div></div><h1>Un piccolo problema.<br>Una grande abitudine.</h1><p>Scrivi Python, scopri cosa ti manca e impara con le sfide giuste per te.</p><div class="eyebrow muted">QUANTI PROBLEMI AL GIORNO?</div><div class="goal-options">${[1,3,5].map(n=>`<button class="goal-choice ${state.goal===n?'active':''}" data-action="onboard-goal" data-goal="${n}">${n}<span>${n===1?'con calma':n===3?'passo costante':'più slancio'}</span></button>`).join('')}</div>${btn(`Cominciamo ${icon('arrow',17)}`,'start','primary full')}<div class="footer-note">Nessun account. Progressi sul dispositivo. Parti dalle basi.</div>`,'onboarding');}
async function runExercise(){if(working||generation||personalJob)return;const e=getExercise(route.id),code=document.getElementById('code-editor').value;working=true;persistEditor();render();try{const result=await runner.run({code,function:e.function,cases:e.cases});const assisted=state.attempts[e.id]?.revealedDay===dayKey(),latestDraft=state.drafts[e.id];const gain=recordAttempt(state,e,{passed:result.passed,assisted,code,error:result.error||'Uno o più test non superati',result});if(latestDraft!==code)state.drafts[e.id]=latestDraft;save();feedback={id:e.id,result,gain};if(route.name==='exercise'&&route.id===e.id)render();else toast(result.passed?'Soluzione verificata e progressi salvati.':'Verifica completata: torna alla sfida per rivedere il risultato.');}catch(error){const result={passed:false,cases:[],output:'',error:error.message};feedback={id:e.id,result};if(error.pythonTimeout)rememberDiagnostic(state,e,code,result);needReview(state,e.lesson);save();if(route.id===e.id)render();}finally{working=false;if(route.name==='exercise'&&route.id===e.id)render();}}
async function generate(track=state.preferred){
  if(generation||working||personalJob||tutor.status.busy)return;
  if(!tutor.status.available){navigate('profile');document.getElementById('tutor-card')?.scrollIntoView({behavior:'smooth',block:'start'});toast('Attiva un modello per creare nuove sfide sul dispositivo.');return;}
  persistEditor();generationError='';generationReady=null;generationTrack=track;const task={track,origin:route,phase:'generating',cancelled:false,attempt:1,started:Date.now(),model:tutor.status.model,accepted:false};generation=task;render();let issue='';
  try{
    for(let attempt=0;attempt<2;attempt++){
      if(task.cancelled)return;task.attempt=attempt+1;task.phase='generating';updateGeneration();
      try{
        const text=await tutor.generate(SYSTEM,generationPrompt(state,track,issue));if(task.cancelled)return;
        const e=parseExercise(text,state,track);task.phase='checking';updateGeneration();
        await verifyGeneratedExercise(e,runner,tutor,()=>task.cancelled,phase=>{task.phase=phase;updateGeneration();});
        if(task.cancelled)return;
        state.generated[e.id]=e;registerGenerated(state.generated);save();task.accepted=true;generation=null;generationReady=e.id;
        if(route===task.origin&&!modalName&&!document.hidden)openExercise(e.id);
        else {if(route.name!=='exercise'&&!modalName)render();else updateGeneration();updatePersonalHintUI();}
        toast('Nuova sfida pronta. La ritrovi in Tutor → Sfide del tutor.');return;
      }catch(error){issue=error.message;if(task.cancelled)return;tutor.recordRejection(attempt+1,issue);if(attempt===1||error.retryable===false)throw error;}
    }
  }catch(error){if(!task.cancelled){generationError=error.message;toast('Il tutor non ha prodotto una sfida valida. Il motivo rimane visibile nella schermata.');}}
  finally{tutor.recordMeasurement({kind:'cycle',model:task.model,track,status:task.cancelled?'cancelled':task.accepted?'accepted':'rejected',elapsedMs:Date.now()-task.started,attempts:task.attempt});if(generation===task){generation=null;updateGeneration();updatePersonalHintUI();}}
}
async function importBackup(text){try{const next=validateState(JSON.parse(text));modal(`<div class="modal-top"><h2>Riprendi da un backup</h2><button class="icon-button" data-action="close-modal" aria-label="Chiudi">${icon('close')}</button></div><p class="lesson-intro">Questo backup contiene ${Object.keys(next.solved).length} risultati e ${next.xp} XP. Sostituirà i progressi attuali sul dispositivo.</p><div class="row">${btn('Importa questi progressi','confirm-import','primary')}${btn('Annulla','close-modal','secondary')}</div>`);window.pendingBackup=next;}catch(error){toast(error.message||'Questo file non è un backup PyDaily valido.');}}
document.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(!button||button.disabled)return;const a=button.dataset.action;if(a==='backdrop'&&event.target!==button)return;event.preventDefault();if(nav.some(([id])=>id===a)){closeModal();navigate(a);return;}switch(a){
case 'track':navigate('track',{track:button.dataset.track});break;
case 'back-track':navigate('track',{track:button.dataset.track});break;
case 'tutor-library':case 'tutor-filter':navigate('tutor',{track:button.dataset.track||'all'});break;
case 'exercise':openExercise(button.dataset.id);break;
case 'next':{const track=button.dataset.track;if(getExercise(route.id)?.generated){const next=generatedProgress(state,track).next;if(next)openExercise(next.exercise.id);else if(tutor.status.available)generate(track);else {navigate('tutor',{track});toast('Attiva un modello per generare altre sfide. Quelle salvate restano disponibili.');}}else openExercise(recommend(state,track).id);break;}
case 'set-preferred':state.preferred=button.dataset.track;save();render();toast('Questo è il tuo percorso quotidiano.');break;
case 'run':runExercise();break;
case 'restart-python':runner.restart();toast('Riavvio Python…');break;
case 'insert':insertCode(button.dataset.value);break;
case 'reset-code':{const e=getExercise(route.id);modal(`<div class="modal-top"><h2>Riparti da zero?</h2><button class="icon-button" data-action="close-modal" aria-label="Chiudi">${icon('close')}</button></div><p class="lesson-intro">Il codice di questo esercizio tornerà alla firma iniziale. I risultati già ottenuti restano salvati.</p><div class="row">${btn('Ripristina codice','confirm-reset')}${btn('Annulla','close-modal','secondary')}</div>`);break;}
case 'confirm-reset':state.drafts[route.id]=getExercise(route.id).starter;save();closeModal();render();break;
case 'hint':{const e=getExercise(route.id);hintCount=Math.min(e.tips.length,hintCount+1);persistEditor();state.attempts[e.id]={...(state.attempts[e.id]||{count:0,failures:0}),tipsUnlocked:hintCount};save();document.getElementById('hint-panel').innerHTML=hintsHTML(e);button.innerHTML=hintLabel(e);break;}
case 'personal-hint':personalHint();break;
case 'cancel-personal-hint':cancelPersonalHint();break;
case 'explain':{const e=getExercise(route.id);needReview(state,e.lesson);save();if(e.generated){modal(`<div class="modal-top"><span class="tag">${icon('brain',14)} Spiegazione del tutor</span><button class="icon-button" data-action="close-modal" aria-label="Chiudi">${icon('close')}</button></div><h2>Prima capiamo il concetto.</h2><p class="lesson-intro">${rich(e.study)}</p>${btn('Apri anche la mini-lezione','lesson','primary',`data-id="${e.lesson}"`)}<p class="footer-caption">Se la consegna non è chiara, puoi creare una sfida diversa.</p>`);}else openLesson(e.lesson);break;}
case 'solution':{const e=getExercise(route.id);persistEditor();state.attempts[e.id]={...(state.attempts[e.id]||{count:0,failures:0}),revealedDay:dayKey()};save();modal(`<div class="modal-top"><span class="tag">${icon('book',13)} SOLUZIONE GUIDATA</span><button class="icon-button" data-action="close-modal" aria-label="Chiudi">${icon('close')}</button></div><h2>Leggila un passo alla volta.</h2><p class="lesson-intro">Questa prova è guidata: puoi eseguirla e studiarla, ma oggi non farà aumentare il livello. Domani potrai riprovarla da te.</p><pre class="solution-code">${esc(e.solution)}</pre><div class="row" style="margin-top:20px;flex-wrap:wrap">${btn('Inserisci nell’editor','copy-solution')}${btn('Torna a provare','close-modal','secondary')}</div>`);break;}
case 'copy-solution':state.drafts[route.id]=getExercise(route.id).solution;save();closeModal();render();break;
case 'lesson':openLesson(button.dataset.id);break;
case 'lesson-practice':{const id=button.dataset.id,l=LESSONS.find(l=>l.id===id);const e=EXERCISES.find(e=>e.lesson===id&&!state.solved[e.id])||EXERCISES.find(e=>e.lesson===id)||recommend(state,l.track);closeModal();openExercise(e.id);break;}
case 'quiz':{const l=LESSONS.find(l=>l.id===button.dataset.id),chosen=Number(button.dataset.index),correct=chosen===l.quiz.answer;reviewAnswer(state,l.id,correct);save();document.querySelectorAll('.quiz-choice').forEach((el,i)=>{el.disabled=true;if(i===l.quiz.answer)el.classList.add('correct');else if(i===chosen)el.classList.add('wrong');});document.getElementById('quiz-explanation').innerHTML=`<p class="quiz-explanation"><b>${correct?'Esatto.':'Rivediamo il passaggio.'}</b> ${esc(l.quiz.explanation)}<br><span class="muted">${correct?'Il prossimo ripasso è programmato.':'Il concetto resta nel ripasso di oggi.'}</span></p>`;break;}
case 'filter':lessonFilter=button.dataset.track;render();break;
case 'goal':state.goal=Number(button.dataset.goal);save();render();break;
case 'onboard-goal':state.goal=Number(button.dataset.goal);onboarding();break;
case 'start':state.onboarded=true;save();closeModal();render();break;
case 'close-modal':case 'backdrop':if(modalName!=='onboarding')closeModal();break;
case 'tutor-settings':navigate('profile');document.getElementById('tutor-card')?.scrollIntoView({behavior:'smooth'});break;
case 'generate':generate(button.dataset.track||state.preferred);break;
case 'cancel-generation':if(generation){generation.cancelled=true;tutor.cancel();if(generation.phase==='checking')runner.restart();generation=null;updateGeneration();updatePersonalHintUI();toast('Generazione interrotta.');}break;
case 'dismiss-generation-error':generationError='';updateGeneration();break;
case 'model-action':modelAction(button.dataset.modelAction);break;
case 'mobile-license':mobileLicense();break;
case 'accept-mobile-license':if(!document.getElementById('fair-consent')?.checked){toast('Leggi e accetta la licenza prima di continuare.');break;}tutor.action('accept-fair-license');closeModal();if(button.dataset.nextAction)tutor.action(button.dataset.nextAction);render();break;
case 'remove-cached-model':{const id=button.dataset.modelId;modal(`<div class="modal-top"><h2>Rimuovere questo modello?</h2><button class="icon-button" data-action="close-modal" aria-label="Chiudi">${icon('close')}</button></div><p class="lesson-intro">Esercizi, bozze e progressi restano salvati. Gli altri modelli rimangono disponibili.</p>${btn('Rimuovi','confirm-remove-cached','secondary',`data-model-id="${esc(id)}"`)}${btn('Annulla','close-modal','primary')}`);break;}
case 'confirm-remove-cached':modelAction('remove:'+button.dataset.modelId);closeModal();render();break;
case 'export-metrics':{const text=JSON.stringify({format:'pydaily-tutor-metrics-v1',measurements:tutor.measurements},null,2);if(window.Native){if(Native.exportTutorMetrics)Native.exportTutorMetrics(text);else Native.exportProgress(text);}else{const url=URL.createObjectURL(new Blob([text],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download='PyDaily-misure-tutor.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}break;}
case 'delete-model':modal(`<div class="modal-top"><h2>Libera lo spazio del modello</h2><button class="icon-button" data-action="close-modal" aria-label="Chiudi">${icon('close')}</button></div><p class="lesson-intro">Rimuovo il modello attivo dal dispositivo. Puoi scaricarlo di nuovo; esercizi, codice e progressi restano salvati.</p><div class="row">${btn('Rimuovi il modello','confirm-delete-model','secondary')}${btn('Annulla','close-modal','primary')}</div>`);break;
case 'confirm-delete-model':modelAction('delete');closeModal();render();break;
case 'reminder':if(window.Native)Native.reminder(!state.reminder.enabled,document.getElementById('reminder-time').value);break;
case 'export':{const text=JSON.stringify(state,null,2);if(window.Native)Native.exportProgress(text);else{const url=URL.createObjectURL(new Blob([text],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='PyDaily-progressi.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}break;}
case 'import':if(window.Native)Native.importProgress();else document.getElementById('backup-file').click();break;
case 'confirm-import':if(working||generation||personalJob){toast('Attendi o annulla la richiesta prima di importare i progressi.');break;}if(window.pendingBackup){state=window.pendingBackup;registerGenerated(state.generated);generationReady=null;generationError='';save();if(window.Native)Native.reminder(false,state.reminder.time);window.pendingBackup=null;closeModal();render();toast('Progressi importati. Il promemoria va riattivato su questo dispositivo.');}break;
}});
document.addEventListener('change',event=>{if(event.target.id==='theme-preference'){if(!window.PyDailyTheme.setPreference(event.target.value))toast('Tema applicato, ma non riesco a salvare la preferenza.');}if(event.target.id==='preferred-track'){state.preferred=event.target.value;save();}if(event.target.id==='reminder-time'){state.reminder.time=event.target.value;save();if(window.Native&&state.reminder.enabled)Native.reminder(true,state.reminder.time);}if(event.target.id==='backup-file'){const file=event.target.files[0];if(file){if(file.size>10*1024*1024){toast('Backup troppo grande.');return;}file.text().then(importBackup);}}});
document.addEventListener('input',event=>{if(event.target.id==='lesson-search'){searchTerm=event.target.value;const lessons=LESSONS.filter(l=>(lessonFilter==='all'||l.track===lessonFilter)&&(l.title+' '+l.intro).toLowerCase().includes(searchTerm.toLowerCase()));document.getElementById('lesson-results').innerHTML=lessonCards(lessons);}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&modalName!=='onboarding')closeModal();if(event.key==='Tab'&&modalName){const focusable=[...modalRoot.querySelectorAll('button:not(:disabled),input,select,textarea,[tabindex="0"]')];if(focusable.length){const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}}});
window.addEventListener('pydaily-import',event=>importBackup(event.detail));
window.addEventListener('pydaily-reminder',event=>{state.reminder={enabled:event.detail.enabled,time:event.detail.time};save();if(route.name==='profile')render();toast(event.detail.enabled?'Promemoria attivato.':'Promemoria disattivato.');});
window.addEventListener('pydaily-theme-change',()=>{const select=document.getElementById('theme-preference');if(select)select.value=window.PyDailyTheme.getPreference();});
window.PyDailyBack=()=>{if(modalName){if(modalName==='onboarding')return false;closeModal();return true;}if(route.name==='exercise'&&getExercise(route.id)?.generated){navigate('tutor',{track:getExercise(route.id).track});return true;}if(route.name!=='home'){navigate('home');return true;}return false;};
if(window.visualViewport)window.visualViewport.addEventListener('resize',()=>document.body.classList.toggle('keyboard-open',window.innerHeight-window.visualViewport.height>140));
window.addEventListener('pagehide',persistEditor);
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&route.name!=='exercise'&&!modalName)render();});
